import json
from pathlib import Path

base = Path(__file__).parent / 'chunks'
translations = {
 't000001': 'Dezvăluirea misterelor saga Jocul lui Ender',
 't000002': 'Dezvăluirea misterelor saga Jocul lui Ender',
 't000003': 'Introducere',
 't000004': 'Universul din Jocul lui Ender, creat de scriitorul american Orson Scott Card, este un reper al literaturii științifico-fantastice moderne. Prezentat pentru prima dată în romanul omonim din 1985, acest viitor imaginat în detaliu îi captivează de decenii pe cititori prin explorarea complexă a locului omenirii într-un cosmos plin de viață extraterestră. Jocul lui Ender înfățișează un viitor în care omenirea a supraviețuit cu greu la două invazii ale unei specii extraterestre insectoide numite „Formicii” sau „Gândacii”. După aceste conflicte, forțele militare internaționale ale Pământului se unesc pentru a se pregăti de o posibilă a treia invazie și se concentrează pe instruirea unor copii excepționali drept comandanți militari într-o instalație orbitală numită Școala de Luptă. Universul Jocului lui Ender se distinge în literatura științifico-fantastică prin câteva elemente esențiale. Tehnologiile avansate, de la comunicarea mai rapidă decât lumina, prin ansiblu, până la simulări de luptă sofisticate, alcătuiesc fundalul crucial al întâmplărilor.',
 't000005': 'Seria îi confruntă constant pe cititori cu întrebări etice dificile, mai ales în privința tratamentului aplicat copiilor, a justificării violenței și a naturii conflictului dintre specii. Opera lui Card este cunoscută pentru examinarea profundă a efectelor psihologice pe care războiul, izolarea și presiunea extremă le au asupra minților tinere. Poveștile prezintă adesea manevre politice complexe, atât pe Pământ, cât și în imperiul interstelar aflat în expansiune al omenirii. În plus, reprezentarea formicilor și a altor specii extraterestre invită la reflecție asupra inteligenței și biologiei nonumane. Influența Jocului lui Ender depășește cu mult literatura științifico-fantastică. Temele și ideile sale își găsesc ecoul în cursuri de strategie militară, în discuții despre psihologia copilului și în dezbateri privind etica războiului. Romanul și continuările sale au inspirat o generație de cititori să reflecteze la complexitatea conducerii, la natura empatiei și la dificultatea de a-i înțelege pe cei profund diferiți de noi.',
 't000006': 'Pe măsură ce vom explora universul Jocului lui Ender, îi vom cerceta fundamentele filosofice, perspectivele antropologice, conceptele științifice și structurile sociale. Vom examina perspectivele sale aparte asupra conducerii, moralității în război și efectelor psihologice ale conflictului. Prin această analiză, încercăm să înțelegem de ce acest univers fictiv continuă să fascineze și să provoace cititorii, oferind idei relevante pentru lumea noastră și pentru viitorurile posibile.',
 't000007': 'Capitolul unu — Efectul Ender: cum a modelat cultura populară un clasic science-fiction',
 't000008': 'Universul Jocului lui Ender, creat de Orson Scott Card, a lăsat o amprentă de neșters asupra culturii populare, depășind granițele literaturii științifico-fantastice și influențând diverse aspecte ale societății moderne. De la publicarea romanului în 1985, acest univers bogat și complex a captivat cititorii, a generat numeroase discuții și i-a inspirat pe creatorii din mai multe medii. În literatură, Jocul lui Ender a redefinit ficțiunea militară science-fiction, introducând teme complexe precum etica războiului și psihologia copiilor supradotați. Explorarea conducerii, strategiei și dilemelor morale într-un cadru futurist a inspirat o generație de autori și multe opere despre teme asemănătoare. Influența sa se vede în literatura științifico-fantastică actuală, preocupată de povara psihologică a conflictului și de implicațiile etice ale tehnologiei avansate. Ecranizarea din 2013 a Jocului lui Ender, cu Asa Butterfield și Harrison Ford, a adus universul în fața unui public mai larg.',
 't000009': 'Deși filmul a primit cronici împărțite și a avut încasări moderate, a stârnit discuții despre dificultatea transpunerii pe ecran a unor concepte science-fiction complexe. Reprezentarea vizuală a Școlii de Luptă și scenele de luptă în imponderabilitate au dat viață descrierilor lui Card, oferindu-le fanilor o imagine concretă a universului Jocului lui Ender. În lumea jocurilor video, deși nu există un joc video oficial Jocul lui Ender, conceptele din carte au influențat considerabil industria. Ideea simulărilor de bătălii spațiale și a strategiilor complexe se regăsește în jocuri precum StarCraft, Halo și Mass Effect. Jocurile de strategie în timp real, în special, datorează mult ideilor din Jocul lui Ender, multe incluzând elemente ce amintesc de scenariile de antrenament din Școala de Luptă. Influența cărții ajunge și în educație, mai ales în conceptul de „gamificare”. Metodele de instruire descrise în roman au inspirat parțial abordări educaționale, îndeosebi în strategia militară și formarea liderilor.',
 't000010': 'Multe instituții de învățământ folosesc elemente din carte pentru a discuta despre etică, leadership și psihologia dezvoltării, ceea ce face din Jocul lui Ender un instrument didactic valoros dincolo de meritele sale literare. În discursul public, termeni și concepte din Jocul lui Ender au intrat în vocabularul fanilor science-fiction. Expresii precum „poarta inamicului este jos”, „Școala de Luptă” și „gândacii” sunt folosite adesea ca referințe culturale în discuțiile despre science-fiction ori strategie. Cartea a devenit un punct de referință în dezbaterile privind etica militară, folosirea copiilor-soldați și manipularea psihologică, fiind frecvent citată în cursuri de etică și filosofie. Seria a strâns o comunitate devotată de fani, cu forumuri online, grupuri de discuții și comunități de ficțiune scrisă de fani. Acolo nu se discută doar cărțile; participanții extind universul, propunând teorii și scenarii alternative. Personajele din Jocul lui Ender, mai ales Ender însuși, sunt subiecte populare pentru costume la convențiile science-fiction, iar fanii recreează cu grijă uniformele Școlii de Luptă și echipamentul de simulare. Jocul lui Ender a inspirat și diverse forme de artă și muzică.',
 't000011': 'Artiști independenți au realizat lucrări inspirate de temele cărții, iar galeriile online sunt pline de interpretări vizuale ale scenelor și personajelor. Deși produsele și obiectele de colecție legate de Jocul lui Ender nu sunt la fel de numeroase ca în cazul altor francize, există ediții speciale ale cărților, postere și replici ale unor obiecte din univers, precum însemnele Școlii de Luptă. În tehnologie și științele spațiale, concepte precum comunicarea instantanee prin ansiblu au stimulat discuții în comunitatea științifică despre posibilitățile comunicării interstelare. Ideile seriei despre călătoria spațială și colonizarea planetelor continuă să inspire cercetători și ingineri, alimentând conversația despre viitorul explorării spațiului. Opiniile personale controversate ale lui Orson Scott Card au generat dezbateri intense despre separarea operei de autor.',
 't000064': 'Moștenirea sa nu constă doar în povestea captivantă și în construirea unui univers viu, ci și în capacitatea de a-i provoca pe cititori să gândească profund la probleme complexe, fără răspunsuri simple. Pe măsură ce traversăm o lume marcată de schimbări tehnologice rapide, provocări globale și concepții în schimbare despre conflict și cooperare, ideile oferite de Jocul lui Ender rămân relevante și provocatoare. Seria amintește că literatura științifico-fantastică poate fi nu doar captivantă, ci și profund semnificativă și stimulatoare intelectual. Ea ne îndeamnă să luăm în considerare consecințele pe termen lung ale acțiunilor noastre, implicațiile etice ale alegerilor și responsabilitățile imense care însoțesc puterea și cunoașterea. Astfel, Jocul lui Ender continuă să inspire noi generații de cititori, gânditori și lideri să abordeze complexitatea lumii cu empatie, gândire strategică și un profund simț al responsabilității morale.',
 't000065': 'Concluzie',
 't000066': 'Impactul seriei Jocul lui Ender depășește lumea literară. Conceptele sale au fost preluate în domenii precum educația militară, teoria conducerii și etica tehnologiei. Ideile din cărți despre strategia militară, psihologia conflictului și dificultățile conducerii în situații de criză rămân relevante și sunt studiate în diverse contexte academice și profesionale. Mai mult, universul Jocului lui Ender rămâne remarcabil de relevant pentru problemele contemporane. Teme precum xenofobia, manipularea prin mass-media, etica inteligenței artificiale și provocările guvernării globale rezonează puternic cu realitățile lumii noastre în continuă schimbare. Seria ne invită să ne examinăm critic propriile societăți și să reflectăm la viitorul pe care îl construim. În cele din urmă, universul Jocului lui Ender demonstrează puterea literaturii științifico-fantastice de a aborda întrebări fundamentale despre condiția umană. Combinând o poveste captivantă cu explorarea aprofundată a unor teme complexe, seria ne provoacă să gândim critic la rolul nostru în univers, la responsabilitățile față de ceilalți și la potențialul nostru atât de distrugere, cât și de înțelegere și creație. Pe măsură ce traversăm o lume tot mai complexă și mai interconectată, lecțiile și întrebările ridicate de Jocul lui Ender rămân relevante și provocatoare, asigurându-i seriei un loc nu doar în canonul science-fiction, ci și în literatură în ansamblu.',
 't000067': 'Bibliografie',
 't000068': '„Jocul lui Ender”, de Orson Scott Card',
 't000069': '„Vorbitor în numele morților”, de Orson Scott Card',
 't000070': '„Xenocid”, de Orson Scott Card',
 't000071': '„Copiii minții”, de Orson Scott Card',
 't000072': '„Jocul lui Ender și filosofia: Poarta logică este jos”, de Jason T. Eberl',
}

for number in (1, 2, 13):
    path = base / f'{number:04d}.json'
    data = json.loads(path.read_text())
    for segment in data['segments']:
        segment['translation'] = translations[segment['id']]
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n')
